const assert = require('node:assert/strict');

const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');
const doc = (id, tenant, owner, extra = {}) => ({ id, tenant, owner, deleted: false, archived: false, ...extra });
const actor = (role, user = 'u', tenant = 'a') => ({ tenant, user, role });
const setup = () => {
  const repo = new DocumentRepository([
    doc('one', 'a', 'u'), doc('other', 'a', 'x'), doc('gone', 'a', 'u', { deleted: true }),
    doc('foreign', 'b', 'u'), doc('done', 'a', 'x', { archived: true }),
  ]);
  return { repo, service: new DocumentService(repo) };
};
const snap = repo => JSON.stringify([repo.documents, repo.audit]);

{
  const repo = new DocumentRepository([doc('one', 'a', 'u')]);
  const service = new DocumentService(repo); const admin = actor('admin');
  service.archive(admin, 'one'); assert.equal(repo.documents[0].archived, true);
  service.archive(admin, 'one'); assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }]);
  assert.throws(() => service.archive(admin, 'missing'), /not found/);
}
{
  const { repo, service } = setup();
  const before = snap(repo);
  for (const role of ['admin', 'editor', 'viewer'])
    for (const id of ['missing', 'gone', 'foreign'])
      assert.throws(() => service.archive(actor(role), id), { message: 'not found' });
  assert.throws(() => service.archive(actor('editor'), 'other'), { message: 'forbidden' });
  assert.throws(() => service.archive(actor('viewer'), 'one'), { message: 'forbidden' });
  assert.throws(() => service.archive(actor('viewer'), 'done'), { message: 'forbidden' });
  assert.throws(() => service.archive(actor('editor'), 'done'), { message: 'forbidden' });
  assert.equal(snap(repo), before);
}
{
  const { repo, service } = setup();
  service.archive(actor('editor'), 'one');
  service.archive(actor('admin', 'boss'), 'other');
  service.archive(actor('admin', 'boss'), 'done');
  assert.deepEqual(repo.audit, [{ actor: 'u', document: 'one' }, { actor: 'boss', document: 'other' }]);
  assert.equal(repo.documents.find(d => d.id === 'other').archived, true);
}
EOF
